head.script:
// https://inswave01.atlassian.net/browse/WAEA-944



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnVisible]<br/>Body Column 정보를 사용하여 특정 Column 의 숨김(Visible) 여부를 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Body Row MultiLine 구성)
//  - gBody 에 <w2:row> 2개 -> 한 데이터 Row 가 2 Line 으로 표시
//  - 1줄 = col1(인덱스0) / col2(인덱스1), 2줄 = col3(인덱스2) / col4(인덱스3)
//  - Row 가 MultiLine 이어도 col1~col4 는 각각 고유 인덱스(0~3) 를 가짐
//  - comp_init 끝에서 2줄 col3(고유 인덱스 2) 를 setColumnVisible(2, false) 로 숨김
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄). 한 데이터 Row 가 2줄에 걸쳐 표시됨. 1줄 col1(0:지점명)/col2(1:매출), 2줄 col3(2:담당자)/col4(3:등급 select, dlt_grade 바인딩) 고유 인덱스. 데이터 Row 3개. comp_init 에서 2줄 col3(고유 인덱스 2) 를 setColumnVisible(2,false) 로 숨김 시도.\n[절차] columnInfo(0~3) 선택 후 (getColumnVisible 실행) -> 선택 인덱스로 getColumnVisible 호출하여 반환값과 getColumnID(인덱스) 매핑 확인.\n[확인] 가이드상 MultiLine 이어도 col1~col4 는 고유 인덱스(0~3) 로 각각 정확한 숨김 여부를 반환해야 함. 각 인덱스 호출 시 반환값(true/false/undefined) 을 관찰."', '', 'label1');

    // select 컬럼(col4) 옵션용 DataList (label/value/visible_info) 동적 생성
    let strGrade = '';
    strGrade += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strGrade += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strGrade += '<w2:column id="visible_info" name="visible_info" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "label": "A등급", "value": "A", "visible_info": "T" },
        { "label": "B등급", "value": "B", "visible_info": "F" },
        { "label": "C등급", "value": "C", "visible_info": "1" },
        { "label": "D등급", "value": "D", "visible_info": "0" }
    ], false);

    // dataList 생성 + 초기값 바인딩 (col1~col4, col4 는 select 등급 값 A/B/C)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "서울 강남점", "col2": "1250", "col3": "김영업", "col4": "A" },
        { "col1": "부산 해운대점", "col2": "980", "col3": "이판매", "col4": "B" },
        { "col1": "대구 수성점", "col2": "1430", "col3": "박상담", "col4": "C" }
    ]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (Body Row MultiLine : gBody 에 <w2:row> 2개)
    //  - 1줄 : col1(0) / col2(1)
    //  - 2줄 : col3(2) / col4(3)
    //  - Row 가 MultiLine 이어도 모든 Column 은 고유 인덱스(0~3)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:560px;height:340px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="지점명"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="매출(만원)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="담당자"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="등급(select)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // index 0 : col1
    strTarget += '<w2:column width="280" inputType="text" id="col1" dataList="col1"></w2:column>';
    // index 1 : col2
    strTarget += '<w2:column width="*" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // index 2 : col3 (2줄 첫 컬럼, 고유 인덱스 2) -> 숨김 대상
    strTarget += '<w2:column width="280" inputType="text" id="col3" dataList="col3"></w2:column>';
    // index 3 : col4 (2줄 마지막, 고유 인덱스 3) - select(dlt_grade 바인딩, setColumnVisibleColumn_3 과 동일 데이터 구성)
    strTarget += '<w2:column width="*" inputType="select" id="col4" dataList="col4">';
    strTarget += '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="label"></w2:label><w2:value ref="value"></w2:value></w2:itemset></w2:choices>';
    strTarget += '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 2줄 col3 (MultiLine 고유 인덱스 2) 를 숨김 -> getColumnVisible(2) 이 false 를 반환하는지 검증용
    target1.setColumnVisible(2, false);
}



// [실행] getColumnVisible : 선택한 컬럼(고유 누적 인덱스) 의 숨김(Visible) 여부를 반환
//  - MultiLine(2줄) 이어도 col1~col4 는 고유 인덱스(0~3) 로 정확히 지목됨
//  - 숨긴 col3(인덱스 2) -> false, 표시 컬럼(0/1/3) -> true
//  - getColumnID(인덱스) 매핑도 함께 출력하여 인덱스 -> 컬럼 ID 대응 확인
scwin.btn_getColumnVisible_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let colID = target1.getColumnID(columnInfo);   // MultiLine Row 에서도 col1~col4 는 고유 인덱스(0~3)
    let isVisible = target1.getColumnVisible(columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("getColumnVisible(" + columnInfo + ") [고유 인덱스 " + columnInfo + " -> getColumnID : " + colID + "] -> 반환값(숨김 여부) : " + isVisible);
}
